/**
 * @summary Get price history aligned to live OANDA spot
 */
export const getGetPriceHistoryUrl = (params?: GetPriceHistoryParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/price-history?${stringifiedParams}`
    : `/api/price-history`;
};

export const getPriceHistory = async (
  params?: GetPriceHistoryParams,
  options?: RequestInit,
): Promise<PriceHistory> => {
  return customFetch<PriceHistory>(getGetPriceHistoryUrl(params), {
    ...options,
    method: "GET",
  });
};

